# [MODULE DOC] Wall-clock and CUDA-event timing helpers plus formatting functions for elapsed seconds.
import datetime
import time

import torch


def format_secs_to_time(time_delta):
    # [FUNCTION DOC] Formats a float number of seconds as "H:MM:SS" (days prefix if >= 1 day), dropping the
    # fractional part.
    """converts seconds delta as generated by 2 snapshots of time.time() into hh:mm:ss"""
    return str(datetime.timedelta(seconds=time_delta)).split(".")[0]


def format_secs_to_sec_fractions(time_delta):
    # [FUNCTION DOC] Formats a float number of seconds as a string with two decimals.
    """converts seconds delta as generated by 2 snapshots of time.time() into ss.msec"""
    return f"{time_delta:0.2f}"


def format_secs_to_sec(time_delta):
    # [FUNCTION DOC] Truncates a float number of seconds to an int.
    """converts seconds delta as generated by 2 snapshots of time.time() into ss"""
    return int(time_delta)


class Timer(object):
    # [CLASS DOC] Wall-clock timer based on time.time() supporting total elapsed time and lap (delta)
    # measurements.
    def __init__(self):
        # [FUNCTION DOC] Creates an unstarted timer (start_time and last_time are None).
        self.start_time = None
        self.last_time = None

    def start(self):
        # [FUNCTION DOC] Records the current time as both start_time and last_time.
        self.start_time = time.time()
        self.last_time = self.start_time

    def delta(self):
        # [FUNCTION DOC] Returns seconds since the previous delta() call (or since start()) and updates
        # last_time to now.
        # Raises TypeError if the timer was never started.
        """delta since last delta call"""
        now = time.time()
        delta = now - self.last_time
        self.last_time = now
        return delta

    def elapsed(self):
        # [FUNCTION DOC] Returns seconds since start(); raises TypeError if not started.
        return time.time() - self.start_time

    def stop(self):
        # [FUNCTION DOC] Returns the elapsed seconds since start() and resets the timer to the unstarted
        # state.
        elapsed = self.elapsed()
        self.start_time = None
        self.last_time = None
        return elapsed


class DeviceAgnosticTimer(object):
    # [CLASS DOC] Timer that uses CUDA events (measuring GPU stream time) when CUDA is available, else
    # time.time().
    def __init__(self):
        # [FUNCTION DOC] Caches whether CUDA is available.
        self.is_cuda_available = torch.cuda.is_available()

    def start(self):
        # [FUNCTION DOC] With CUDA: creates timing-enabled start/end CUDA events and records the start event
        # on the current stream.
        # Without CUDA: stores the current wall-clock time.
        if self.is_cuda_available:
            self.start_event = torch.cuda.Event(enable_timing=True)
            self.end_event = torch.cuda.Event(enable_timing=True)
            self.start_event.record()
        else:
            self.start_event = time.time()

    def stop(self):
        # [FUNCTION DOC] Returns elapsed seconds since start(). With CUDA records the end event, calls
        # torch.cuda.synchronize()
        # (blocking) and converts the event elapsed milliseconds to seconds; otherwise uses wall-clock
        # difference.
        # Fails with AttributeError if start() was not called.
        if self.is_cuda_available:
            self.end_event.record()
            torch.cuda.synchronize()
            diff = self.start_event.elapsed_time(self.end_event) / 1000
        else:
            self.end_event = time.time()
            diff = self.end_event - self.start_event
        return diff
